def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    fixed_135_count = 0
    aggressive_count = 0
    rich_alive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 135:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if abs(bid - 135.0) < 1e-9:
                    fixed_135_count += 1
                if bid >= 110:
                    aggressive_count += 1

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return max(0, min(budget, 40.0))
        return max(0, min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    emergency = hp <= 2 or no_water_days >= 2
    danger = hp <= 4 or no_water_days >= 1
    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if emergency:
        target = max(110.0, highest_prev + 2.5)
        if fixed_135_count > 0 and budget >= 136:
            target = max(target, 136.0)
        return max(0, min(budget, target))

    if tight_supply:
        if danger:
            target = max(95.0, highest_prev + 2.0)
            if fixed_135_count > 0 and budget >= 136 and hp <= 3:
                target = max(target, 136.0)
            return max(0, min(budget, target))
        lowball = 8.0 + 2.0 * no_water_days
        if aggressive_count >= 2:
            lowball = 5.0
        return max(0, min(budget, lowball))

    if ample_supply:
        if highest_prev >= 130 and hp >= 5:
            return max(0, min(budget, 42.0))
        target = max(48.0, min(88.0, avg_prev + 3.0))
        if day >= 8:
            target += 8.0
        return max(0, min(budget, target))

    target = 0.0
    if highest_prev >= 130:
        if hp >= 6 and no_water_days == 0:
            target = 38.0
        else:
            target = 96.0
    elif highest_prev >= 110:
        target = highest_prev + 2.0
    elif highest_prev > 0:
        target = max(52.0, highest_prev + 1.5)
    else:
        target = 50.0

    if rich_alive >= 2 and hp >= 5 and no_water_days == 0 and target > 90:
        target = 72.0

    if day >= 9 and hp <= 5:
        target = max(target, 92.0)

    return max(0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive.append(opp)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer who overbids.
    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many bidders likely needed water.
    # With supply 15..25 and requirement 9, at most 2 units/day are typically available.
    # So we should not overpay against a known high bidder.
    if supply <= WATER_REQ:
        base = DAILY_SALARY * 0.9
    else:
        # More supply means we can bid less.
        ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
        ratio = max(0.0, min(1.0, ratio))
        base = DAILY_SALARY * (0.55 + 0.25 * ratio)  # ~0.55..0.80

    # If opponent(s) were bidding extremely high yesterday, assume they are trying to secure water.
    # We can undercut slightly unless our hp is critical.
    if highest_prev_bid >= 0.9 * DAILY_SALARY * 1.5:  # ~121.5 threshold
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        else:
            # Undercut: bid enough to have a chance but not match.
            target = min(base, DAILY_SALARY * 0.65)
    else:
        # Otherwise bid near base, with urgency if we're already in no-water streak.
        if hp <= 2.0:
            target = DAILY_SALARY * 0.95
        elif no_water_days >= 2:
            target = DAILY_SALARY * 0.8
        else:
            target = base

    # Never bid more than budget.
    bid = max(0.0, min(budget, target))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    VALUE_PER_UNIT = DAILY_SALARY / WATER_REQ

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return int(min(my_status['budget'], WATER_REQ * VALUE_PER_UNIT * 0.5))

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace')
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    max_yesterday_bid = max(yesterday_bids) if yesterday_bids else 0.0

    bid = 0.0

    # Priority 1: Survival Mode - If HP is critically low or I've missed water previously
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        bid = DAILY_SALARY * 1.2
        if max_yesterday_bid > 0:
            bid = max(bid, max_yesterday_bid + VALUE_PER_UNIT * 2)
        bid = max(bid, DAILY_SALARY * 0.9)
    else:
        supply = day_context['supply']
        num_potential_winners = len(alive_opponents) + 1

        total_water_needed_by_all = num_potential_winners * WATER_REQ

        if supply >= total_water_needed_by_all * 1.2:
            bid = DAILY_SALARY * 0.6
            if max_yesterday_bid > 0:
                bid = max(bid, max_yesterday_bid * 0.9)
            bid = min(bid, DAILY_SALARY * 0.75)
        elif supply < total_water_needed_by_all * 0.8:
            bid = DAILY_SALARY * 1.0
            if max_yesterday_bid > 0:
                bid = max(bid, max_yesterday_bid + VALUE_PER_UNIT * 1.5)
            bid = min(bid, DAILY_SALARY * 1.3)
        else:
            bid = DAILY_SALARY * 0.8
            if max_yesterday_bid > 0:
                bid = max(bid, max_yesterday_bid + VALUE_PER_UNIT * 0.5)
            bid = min(bid, DAILY_SALARY * 1.1)

    bid = min(bid, my_status['budget'])
    bid = max(bid, WATER_REQ * VALUE_PER_UNIT * 0.1)
    bid = max(bid, 1.0)

    return int(bid)

